INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-5', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-057-6', 'p0242', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '皓悖虐，固與陸凱、孟宗同心憂國，年七十六卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-059-7', 'p0242', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '靈輿當至，使丞相陸凱奉三牲祭於近郊，皓於金城外露宿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-061-8', 'p0242', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '陸凱字敬風，吳郡吳人，丞相遜族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-061-9', 'p0242', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '評曰：潘濬公清割斷，陸凱忠壯質直，皆節槩梗梗，有大丈夫格業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-065-10', 'p0242', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '丞相陸凱上疏曰：「常侍王蕃黃中通理，知天知物，處朝忠蹇，斯社稷之重鎮，大吳之龍逢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-035-0', 'p0243', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '於是儀結陣而去，入谷然後發喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-1', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '是儀字子羽，北海營陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-2', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '徐衆評曰：是儀以羈旅異方，客仕吳朝，值讒邪殄行，當嚴毅之威，命縣漏刻，禍急危機，不雷同以害人，不苟免以傷義，可謂忠勇公正之士，雖祁奚之免叔向，慶忌之濟朱雲，何以尚之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-3', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '鄰家有起大宅者，權出望見，問起大室者誰，左右對曰：「似是儀家也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-4', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '權歎曰：「使人盡如是儀，當安用科法為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-5', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '權為車騎將軍，都京，召綜還，為書部，與是儀、徐詳俱典軍國密事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-6', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-047-0', 'p0244', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」將軍胡綜議，以為「喪紀之禮，雖有典制，苟無其時，所不得行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-056-1', 'p0244', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時全琮為督，權又令偏將軍胡綜宣傳詔命，參與軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-056-2', 'p0244', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '琮欲自解，因曰：「上自令胡綜為督，綜意以為宜爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-059-3', 'p0244', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '江表傳曰：登使侍中胡綜作賔友目曰：「英才卓越，超踰倫匹，則諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-060-4', 'p0244', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃武中，鄱陽大帥彭綺作亂，攻沒屬城，乃以魴為鄱陽太守，與胡綜戮力攻討，遂生禽綺，送詣武昌，加昭義校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-061-5', 'p0244', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先帝外仗顧、陸、朱、張，內近胡綜、薛綜，是以庶績雍熈，邦內清肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-062-6', 'p0244', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '胡綜字偉則，汝南固始人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-062-7', 'p0244', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-008-0', 'p0245', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謙重令楊州從事會稽吳範宣旨，昱守意不移；欲威以刑罰，然後乃起。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-048-1', 'p0245', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-057-2', 'p0245', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其探極祕術，言合神明，則太史令上虞吳範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-3', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '吳範字文則，會稽上虞人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-4', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」曰：「使汝為吳範死，子以屬我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-5', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權追思之，募三州有能舉知術數如吳範、趙達者，封千戶侯，卒無所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-0', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲諸葛恪帥軍更於隄左右結山，挾築兩城，使全端、留略守之，引軍而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-1', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月，吳大將軍諸葛恪拒戰，大破衆軍於東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-2', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五月，吳太傅諸葛恪圍合肥新城，詔太尉司馬孚拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-3', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '及諸葛恪圍城，特與將軍樂方等三軍衆合有三千人，吏兵疾病及戰死者過半，而恪起土山急攻，城將陷，不可護。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-4', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '六年春二月己丑，鎮東將軍毌丘儉上言：「昔諸葛恪圍合肥新城，城中遣士劉整出圍傳消息，為賊所得，考問所傳，語整曰：『諸葛公欲活汝，汝可具服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-015-5', 'p0246', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '數為國家陳擊吳、蜀形勢，又嘗對司馬大將軍料諸葛恪雖得勝於邊土，見誅不乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-015-6', 'p0246', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '大將軍聞恪死，謂衆人曰：「諸葛恪多輩耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-7', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今權以死，託孤於諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-8', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今權已死，託孤於諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-9', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '五年正月，諸葛恪拒戰，大破衆軍於東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-10', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '後吳大將諸葛恪新破東關，乘勝揚聲欲向青、徐，朝廷將為之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-027-11', 'p0246', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基諫曰：「昔諸葛恪乘東關之勝，竭江表之兵，以圍新城，城旣不拔，而衆死者太半。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-12', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-13', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛恪興東關，遣誕督諸軍討之，與戰，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-14', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛恪圍合肥新城，不克，退歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-15', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾矯然彊壯，立功立事，然闇於防患，咎敗旋至，豈遠知乎諸葛恪而不能近自見，此蓋古人所謂目論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-035-16', 'p0246', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛恪見誅於吳，子孫皆盡，而亮自有胄裔，故攀還復為瑾後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-035-17', 'p0246', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-043-18', 'p0246', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '吳太傅諸葛恪以初破魏軍，大興兵衆以圖攻取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-044-19', 'p0246', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '孫權性旣滑稽，嘲啁無方，諸葛恪、羊衜等才愽果辯，論難鋒至，禕辭順義篤，據理以荅，終不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-20', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋八月，以諸葛恪為丹陽太守，討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-21', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '諸葛恪平山越事畢，北屯廬江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-22', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '威北將軍諸葛恪攻六安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-23', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '諸葛恪征六安，破魏將謝順營，收其民人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-24', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，司馬宣王率軍入舒，諸葛恪自皖遷于柴桑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-25', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-26', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，權寢疾，徵大將軍諸葛恪為太子太傅，會稽太守滕胤為太常，並受詔輔太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-27', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳錄云：諸葛恪有遷都意，更起武昌宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-28', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '四月，權薨，休弟亮承統，諸葛恪秉政，不欲諸王在濵江兵馬之地，徙休於丹楊郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-29', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '後常為諸葛恪司馬，幹恪府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-051-30', 'p0246', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-31', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '又諸葛恪年少時，衆人奇其英才，承言終敗諸葛氏者元遜也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-32', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '休字叔嗣，弱冠與諸葛恪、顧譚等俱為太子登僚友，以漢書授登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-33', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '譚字子默，弱冠與諸葛恪等為太子四友，從中庶子轉輔正都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-34', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '時四方之傑畢集，太傅諸葛恪以雄奇蓋衆，而譚以清識絕倫，獨見推重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-35', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後為吳郡西部都尉，與諸葛恪等共平山越，別得精兵八千人，還屯軍章阬，拜昭義中郎將，入為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-36', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」後有呂範、諸葛恪為說隲所言，云：「每讀步隲表，輒失笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-053-37', 'p0246', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '酒酣，禕與諸葛恪相對嘲難，言及吳、蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-38', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '東興之役，綜為前鋒，軍敗身死，諸葛恪斬送其首，以白權廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-39', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '弟表，字文奧，武庶子也，少知名，與諸葛恪、顧譚、張休等並侍東宮，皆共親友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-40', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '嘉禾三年，諸葛恪領丹楊太守，討平山越，以表領新安都尉，與恪參勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-41', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏遣諸葛誕、胡遵等攻東興，諸葛恪率軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-056-42', 'p0246', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，孫峻殺諸葛恪，遷據為驃騎將軍，平西宮事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-056-43', 'p0246', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳書曰：異又隨諸葛恪圍新城，城旣不拔，異等皆言宜速還豫章，襲石頭城，不過數日可拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-057-44', 'p0246', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '諸葛恪為丹楊太守，討山越，以平威重思慮，可與效力，請平為丞，稍遷武昌左部督，傾心接物，士卒皆為盡力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-45', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又謂諸葛恪曰：「在我前者，吾必奉之同升；在我下者，則扶持之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-46', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '赤烏九年，遷立節中郎將，與諸葛恪換屯柴桑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-47', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '文士傳曰：陸景母張承女，諸葛恪外生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-48', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '是歲，立登為太子，選置師傅，銓簡秀士，以為賔友，於是諸葛恪、張休、顧譚、陳表等以選入，侍講詩書，出從騎射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-49', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '江表傳曰：登使侍中胡綜作賔友目曰：「英才卓越，超踰倫匹，則諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-50', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛恪才略博達，器任佐時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-51', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-52', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '四月，權薨，諸葛恪秉政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-53', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權薨，太傅諸葛恪不欲諸王處江濵兵馬之地，徙奮於豫章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-060-54', 'p0246', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及陸遜卒，諸葛恪代遜，權乃分武昌為兩部，岱督右部，自武昌上至蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-55', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛恪字元遜，瑾長子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-56', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '後蜀使至，群臣並會，權謂使曰：「此諸葛恪雅好騎乘，還告丞相，為致好馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-57', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '峻起如廁，解長衣，著短服，出曰：「有詔收諸葛恪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-58', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '先是，童謠曰：「諸葛恪，蘆葦單衣篾鉤落，於何相求成子閣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-59', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '伏念故太傅諸葛恪得承祖考風流之烈，伯叔諸父遭漢祚盡，九州鼎立，分託三方，並履忠勤，熈隆世業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-60', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '太元元年，權寢疾，詣都，留為太常，與諸葛恪等俱受遺詔輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-61', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '旣誅諸葛恪，遷丞相大將軍，督中外諸軍事，假節，進封富春侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-62', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛恪征東興，贊為前部，合戰先陷陣，大敗魏師，遷左將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-63', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '據御軍齊整，峻惡之，稱心痛去，遂夢為諸葛恪所擊，恐懼發病死，時年三十八，以後事付綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-64', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '初，峻從弟慮與誅諸葛恪之謀，峻厚之，至右將軍、無難督，授節蓋，平九官事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-65', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-66', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '評曰：諸葛恪才氣幹略，邦人所稱，然驕且吝，周公無觀，況在於恪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-065-67', 'p0246', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫亮即位，諸葛恪輔政，表曜為太史令，撰吳書，華覈、薛瑩等皆與參同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-001-68', 'p0246', 'jinshu', 'a05-001', '《晉書·卷一》', '先是，吳遣將諸葛恪屯皖，邊鄙苦之，帝欲自擊恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-001-69', 'p0246', 'jinshu', 'a05-001', '《晉書·卷一》', '四年秋九月，帝督諸軍擊諸葛恪，車駕送出津陽門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-002-70', 'p0246', 'jinshu', 'a05-002', '《晉書·卷二》', '五年夏五月，吳太傅諸葛恪圍新城，朝議慮其分兵以寇淮泗，欲戍諸水口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-002-71', 'p0246', 'jinshu', 'a05-002', '《晉書·卷二》', '帝曰：「諸葛恪新得政於吳，欲徼一時之利，并兵合肥，以冀萬一，不暇復為青徐患也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-013-72', 'p0246', 'jinshu', 'a05-013', '《晉書·卷十三》', '是月，宣帝討諸葛恪，恪棄城走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-013-73', 'p0246', 'jinshu', 'a05-013', '《晉書·卷十三》', '六月，宣帝討諸葛恪於皖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-037-74', 'p0246', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時吳將諸葛恪圍新城，以孚進督諸軍二十萬防禦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-048-0', 'p0247', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，權寢疾，徵大將軍諸葛恪為太子太傅，會稽太守滕胤為太常，並受詔輔太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-048-1', 'p0247', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '據、欽、咨等表薦衞將軍滕胤為丞相，綝不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-050-2', 'p0247', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '纂妻即滕胤女也，胤被誅，并遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-050-3', 'p0247', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '夫人立為皇后，以尚為城門校尉，封都亭侯，代滕胤為太常、衞將軍，進封永平侯，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-051-4', 'p0247', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '咨為滕胤所殺，儀為孫峻所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-051-5', 'p0247', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-052-6', 'p0247', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：昭與孫紹、滕胤、鄭禮等，採周、漢，撰定朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-059-7', 'p0247', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-060-8', 'p0247', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '始興太守羊衜與太常滕胤書曰：「鍾離子幹吾昔知之不熟，定見其在南海，威恩部伍，智勇分明，加操行清純，有古人之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-9', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」又問：「卿何如滕胤？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-10', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-11', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '未出路門，逢太常滕胤，恪曰：「卒腹痛，不任入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-12', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '吳歷曰：張約、朱恩密疏告恪，恪以示滕胤，胤勸恪還，恪曰：「峻小子何能為邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-13', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '始恪退軍還，聶友知其將敗，書與滕胤曰：「當人彊盛，河山可拔，一朝羸縮，人情萬端，言之悲歎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-14', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤字承嗣，北海劇人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-15', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤以恪子竦妻父辭位，峻曰：「鯀禹罪不相及，滕侯何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-16', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時有媚峻者，以為大統宜在公族，若滕胤為亞公，聲名素重，衆心所附，不可貳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-17', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '唯滕胤諫止，不從，而功竟不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-18', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-19', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臣松之以為孫綝雖凶虐，與滕胤宿無嫌隙，胤若且順綝意，出鎮武昌，豈徒免當時之禍，仍將永保元吉，而犯機觸害，自取夷滅，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-20', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」休曰：「卿何以不徙滕胤、呂據？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-21', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-22', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤厲脩士操，遵蹈規矩，而孫峻之時猶保其貴，必危之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-004-0', 'p0248', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，吳大將孫峻等衆號十萬至壽春，諸葛誕拒擊破之，斬吳左將軍留贊，獻捷于京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-1', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '戰敗走，晝夜間行，追者不及，遂得入吳，孫峻厚待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-2', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-3', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳大將軍孫峻等號十萬衆，將渡江，鎮東將軍諸葛誕遣艾據肥陽，艾以與賊勢相遠，非要害之地，輒移屯附亭，遣泰山太守諸葛緒等於黎漿拒戰，遂走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-048-4', 'p0248', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '武衞將軍孫峻伏兵殺恪於殿堂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-048-5', 'p0248', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '初為中書郎，孫峻使詰南陽王和，令其引分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-050-6', 'p0248', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '建興中，孫峻專政，公族皆患之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-050-7', 'p0248', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '搜神記曰：孫峻殺朱主，埋於石子岡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-051-8', 'p0248', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '咨為滕胤所殺，儀為孫峻所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-051-9', 'p0248', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-055-10', 'p0248', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將文欽來降，以奉為虎威將軍，從孫峻至壽春迎之，與敵追軍戰於高亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-056-11', 'p0248', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，孫峻殺諸葛恪，遷據為驃騎將軍，平西宮事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-056-12', 'p0248', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '太平元年，帥師侵魏，未及淮，聞孫峻死，以從弟綝自代，據大怒，引軍還，欲廢綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-13', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '五鳳元年，英以大將軍孫峻擅權，謀誅峻，事覺自殺，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-14', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權患之，謂侍中孫峻曰：「子弟不睦，臣下分部，將有袁氏之敗，為天下笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-15', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '吳書曰：權寢疾，意頗感寤，欲徵和還立之，全公主及孫峻、孫弘等固爭之，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-16', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '及恪被誅，孫峻因此奪和璽綬，徙新都，又遣使者賜死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-17', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-18', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時朝臣咸皆注意於恪，而孫峻表恪器任輔政，可付大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-19', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻因民之多怨，衆之所嫌，構恪欲為變，與亮謀，置酒請恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-20', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」婢蹷然起躍，頭至于棟，攘臂切齒而言曰：「諸葛公乃為孫峻所殺！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-21', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」恪誅後，孫峻忌友，欲以為鬱林太守，友發病憂死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-22', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻字子遠，孫堅弟靜之曾孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-23', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻征淮南，授贊節，拜左護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-24', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '亮內嫌綝，乃推魯育見殺本末，責怒虎林督朱熊、熊弟外部督朱損不匡正孫峻，乃令丁奉殺熊於虎林，殺損於建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-25', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '發孫峻棺，取其印綬，斲其木而埋之，以殺魯育等故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-26', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤厲脩士操，遵蹈規矩，而孫峻之時猶保其貴，必危之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a05-002-27', 'p0248', 'jinshu', 'a05-002', '《晉書·卷二》', '孫峻猾夏，致寇徐方，戎車首路，威靈先邁，黃鉞未啟，鯨鯢竄迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-0', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '孫綝以異戰不進，怒而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-1', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-2', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '況公今舉十餘萬之衆內附，而欽與全端等皆同居死地，父兄子弟盡在江表，就孫綝不欲，主上及其親戚豈肯聽乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-033-3', 'p0249', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '吳大將軍孫綝廢其主亮，立琅邪王休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-048-4', 'p0249', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮廢，己未，孫綝使宗正孫楷與中書郎董朝迎休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-050-5', 'p0249', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會孫綝廢亮為會稽王，後又黜為候官侯，夫人隨之國，居候官，尚將家屬徙零陵，追見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-050-6', 'p0249', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '損妻是峻妹也，孫綝益忌亮，遂廢亮，立休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-051-7', 'p0249', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-055-8', 'p0249', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-056-9', 'p0249', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫綝秉政，大臣疑貳，績恐吳必擾亂，而中國乘釁，乃密書結蜀，使為并兼之慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-057-10', 'p0249', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫綝廢幼主，迎立琅邪王休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-11', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫綝字子通，與峻同祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-12', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臣松之以為孫綝雖凶虐，與滕胤宿無嫌隙，胤若且順綝意，出鎮武昌，豈徒免當時之禍，仍將永保元吉，而犯機觸害，自取夷滅，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-13', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '江表傳曰：亮召全尚息黃門侍郎紀密謀，曰：「孫綝專勢，輕小於孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a05-013-14', 'p0249', 'jinshu', 'a05-013', '《晉書·卷十三》', '」太平三年，孫綝盛兵圍宮，廢亮為會稽王，故國志又書於吳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-0', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬十月，以衞將軍濮陽興為丞相，廷尉丁密、光祿勳孟宗為左右御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-1', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '癸未，休薨，江表傳曰：休寢疾，口不能言，乃手書呼丞相濮陽興入，令子𩅦出拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-2', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '左典軍萬彧昔為烏程令，與皓相善，稱皓才識明斷，是長沙桓王之疇也，又加之好學，奉遵法度，屢言之於丞相濮陽興、左將軍張布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-055-3', 'p0250', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '休薨，奉與丞相濮陽興等從萬彧之言，共迎立孫皓，遷右大司馬左軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-057-4', 'p0250', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '太守濮陽興正旦宴見掾吏，言次，問：「太守昔聞朱潁川問士於鄭召公，韓吳郡問士於劉聖博，王景興問士於虞仲翔，甞見鄭、劉二荅而未覩仲翔對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-064-5', 'p0250', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '濮陽興字子元，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-064-6', 'p0250', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '濮陽興身居宰輔，慮不經國，協張布之邪，納萬彧之說，誅夷其宜矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0251-a04-051-0', 'p0251', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫翊字叔弼，權弟也，驍悍果烈，有兄策風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0251-a04-051-1', 'p0251', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '憲故孝廉媯覽、戴員亡匿山中，孫翊為丹楊，皆禮致之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-051-0', 'p0252', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫桓字叔武，河之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-058-1', 'p0252', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-058-2', 'p0252', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '初，孫桓別討備前鋒於夷道，為備所圍，求救於遜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-003-0', 'p0253', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權入居巢湖口，向合肥新城，又遣將陸議、孫韶各將萬餘人入淮、沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-1', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '孫韶又遣將高壽等率敢死之士五百人於徑路夜要之，帝大驚，壽等獲副車羽蓋以還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-2', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-3', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '未至壽春，權退還，孫韶亦罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-051-4', 'p0253', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '吳歷載翊妻徐節行，宜與媯覽等事相次，故列於後孫韶傳中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-056-5', 'p0253', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-060-6', 'p0253', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0254-a04-047-0', 'p0254', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0255-a04-060-0', 'p0255', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東主中營自掩石陽，別遣從弟孫奐治安陸城，脩立邸閣，輦貲運糧，以為軍儲，又命諸葛亮進指關西，江邊諸將無復在者，才留三千所兵守武昌耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-028-0', 'p0256', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽雖在他國，不能屈節下人，自呂據、朱異等諸大將皆憎疾之，惟峻常左右之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-028-1', 'p0256', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-047-2', 'p0256', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-048-3', 'p0256', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '閏月壬辰，峻及驃騎將軍呂據、左將軍留贊率兵襲壽春，軍及東興，聞欽等敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-048-4', 'p0256', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '八月，先遣欽及驃騎呂據、車騎劉纂、鎮南朱異、前將軍唐咨軍自江都入淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-051-5', 'p0256', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-055-6', 'p0256', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '」及恪上岸，奉與將軍唐咨、呂據、留贊等，俱從山西上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-056-7', 'p0256', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」乃遣呂據督二萬人，與異并力，至北界，欽果不降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-056-8', 'p0256', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-059-9', 'p0256', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-10', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-11', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪遣將軍留贊、呂據、唐咨、丁奉為前部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-12', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-13', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-14', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-15', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」休曰：「卿何以不徙滕胤、呂據？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-16', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-057-0', 'p0257', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '休初即位，汜與賀邵、王蕃、薛瑩俱為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-058-1', 'p0257', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '故大司農樓玄、散騎中常侍王蕃、少府李勗，皆當世秀頴，一時顯器，旣蒙初寵，從容列位，而並旋受誅殛，或圮族替祀，或投棄荒裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-061-2', 'p0257', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '中常侍王蕃黃中通理，處朝忠謇，斯社稷之重鎮，大吳之龍逄也，而陛下忿其苦辭，惡其直對，梟之殿堂，尸骸暴棄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-3', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '王蕃字永元，廬江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-4', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '丞相陸凱上疏曰：「常侍王蕃黃中通理，知天知物，處朝忠蹇，斯社稷之重鎮，大吳之龍逢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-5', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，與王蕃、郭逴、萬彧俱為散騎中常侍，出為會稽太守，入為大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-6', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '故常侍王蕃忠恪在公，才任輔弼，以醉酒之間加之大戮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-7', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a05-011-8', 'p0257', 'jinshu', 'a05-011', '《晉書·卷十一》', '至吳時，中常侍廬江王蕃善數術，傳劉洪乾象歷，依其法而制渾儀，立論考度曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a05-017-9', 'p0257', 'jinshu', 'a05-017', '《晉書·卷十七》', '中常侍王蕃以洪術精妙，用推渾天之理，以制儀象及論，故孫氏用乾象歷，至吳亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-048-0', 'p0258', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-058-1', 'p0258', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '故大司農樓玄、散騎中常侍王蕃、少府李勗，皆當世秀頴，一時顯器，旣蒙初寵，從容列位，而並旋受誅殛，或圮族替祀，或投棄荒裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-061-2', 'p0258', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '姚信、樓玄、賀卲、張悌、郭逴、薛瑩、滕脩及族弟喜、抗，或清白忠勤，或姿才卓茂，皆社稷之楨幹，國家之良輔，願陛下重留神思，訪以時務，各盡其忠，拾遺萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-3', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '樓玄字承先，沛郡蘄人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-4', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '臣夙夜思惟，諸吏之中，任幹之事，足委杖者，無勝於樓玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-5', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '乃共譖邵與樓玄謗毀國事，俱被詰責，玄見送南州，邵原復職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-6', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-057-0', 'p0259', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '休初即位，汜與賀邵、王蕃、薛瑩俱為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-1', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，與賀邵、薛瑩、虞汜俱為散騎中常侍，皆加駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-2', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '後人誣白玄與賀邵相逢，駐共耳語大笑，謗訕政事，遂被詔詰責，送付廣州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-3', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '賀邵字興伯，會稽山陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-4', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-005-0', 'p0260', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」韋昭云：「大行者，不反之辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-040-1', 'p0260', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」韋昭注曰：「璫，榱頭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-042-2', 'p0260', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '韋昭注國語曰：「有眸子而無見曰矇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-052-3', 'p0260', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」韋昭注云：「六柄，生、殺、貧、賤、富、貴也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-058-4', 'p0260', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '』」韋昭注曰：「燿，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-075-5', 'p0260', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '又聞孫堅得傳國璽，韋昭吳書曰：「漢室大亂，天子北詣河上，六璽不自隨，掌璽者以投井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-078-6', 'p0260', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」韋昭曰：「古者腐刑必熏合之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-078-7', 'p0260', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '節弟破石為越騎校尉，越騎營五百妻有美色，韋昭辯釋名曰：「五百字本為『伍』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-083-8', 'p0260', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '」韋昭注云：「側猶特也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-094-9', 'p0260', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」韋昭曰：「借民力以治之，以奉宗廟；且以勸率天下，使務農也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-099-10', 'p0260', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '韋昭曰：「古者穴居，故名室中為中霤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-100-11', 'p0260', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '」韋昭曰：「自下往觸之曰犯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-12', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」酈食其說曰「杜太行之道」，韋昭曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-13', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」韋昭曰：「戎來居此山，故號驪戎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-14', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '太史公曰「遷生龍門」，韋昭曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-112-15', 'p0260', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '」句踐欲遷吳王於甬東，韋昭曰縣東洲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-116-16', 'p0260', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '本注曰：成帝初置尚書四人，韋昭曰：「尚，奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-117-17', 'p0260', 'houhanshu', 'a03-117', '《二十四史-後漢書-志第二十七‧百官四》', '」韋昭曰：「長水校尉典胡騎，廄近長水，故以為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a04-001-18', 'p0260', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '君糾虔天刑，章厥有罪，「糾虔天刑」語出國語，韋昭注曰：「糾，察也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a04-016-19', 'p0260', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韋昭國語註稱毛詩傳曰：「冥，契六世孫也，為夏水官，勤於其職而死於水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-025-0', 'p0262', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』逮鍾會為鎮西將軍，憲英謂從子羊祜曰：『鍾士季何故西出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-048-1', 'p0262', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '尚書僕射羊祜、尚書何楨並結縞帶之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-052-2', 'p0262', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '命車騎將軍羊祜、荊州刺史楊肇往赴救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-3', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '晉車騎將軍羊祜率師向江陵，諸將咸以抗不宜上，抗曰：「江陵城固兵足，無所憂患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-4', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '晉陽秋曰：抗與羊祜推僑、札之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-5', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '漢晉春秋曰：羊祜旣歸，增脩德信，以懷吳人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-6', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '是以羊祜恢大同之略，思五兵之則，齊其民人，均其施澤，振義網以羅彊吳，明兼愛以革暴俗，易生民之視聽，馳不戰乎江表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-7', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '以中軍將軍羊祜為尚書左僕射，東莞王伷為尚書右僕射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-8', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '壬寅，以尚書左僕射羊祜都督荊州諸軍事，征東大將軍衞瓘都督青州諸軍事，東莞王伷鎮東大將軍、都督徐州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-9', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將陸抗攻闡，遣車騎將軍羊祜帥衆出江陵，荊州刺史楊肇迎闡於西陵，巴東監軍徐胤擊建平以救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-10', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '以故太傅鄭沖、太尉荀顗、司徒石苞、司空裴秀、驃騎將軍王沈、安平獻王孚等及太保何曾、司空賈充、太尉陳騫、中書監荀勗、平南將軍羊祜、齊王攸等皆列於銘饗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-11', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '冬十月，以汝陰王駿為征西大將軍，平南將軍羊祜為征南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-12', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '立皇子瑋為始平王，允為濮陽王，該為新都王，遐為清河王，鉅平侯羊祜為南城侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-005-13', 'p0262', 'jinshu', 'a05-005', '《晉書·卷五》', '腹心不同，公卿異議，而獨納羊祜之策，杖王杜之決，役不二時，江湘來同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-013-14', 'p0262', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是時羊祜表求伐吳，上許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-019-15', 'p0262', 'jinshu', 'a05-019', '《晉書·卷十九》', '及晉國建，文帝又命荀顗因魏代前事，撰為新禮，參考今古，更其節文，羊祜、任愷、庾峻、應貞並共刊定，成百六十五篇，奏之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-16', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '羊祜字叔子，泰山南城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-17', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '人多諫抗，抗曰：「羊祜豈酖人者！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-18', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '故太傅、鉅平侯羊祜明德通賢，國之宗主，勳參佐命，功成平吳，而後嗣闕然，烝嘗莫寄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-19', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '時帝密有滅吳之計，而朝議多違，唯預、羊祜、張華與帝意合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-20', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」預旬月之中又上表曰：「羊祜與朝臣多不同，不先博畫而密與陛下共施此計，故益令多異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-full-21', 'p0262', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，帝潛與羊祜謀伐吳，而羣臣多以爲不可，唯華贊成其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-full-22', 'p0262', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-23', 'p0262', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，帝潛與羊祜謀伐吳，而羣臣多以爲不可，唯華贊成其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-24', 'p0262', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-25', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈以才望，顯名當世，是以創業之事，羊祜、荀勖、裴秀、賈充等，皆與沈諮謀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-26', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '顗上請羊祜、任愷、庾峻、應貞、孔顥共刪改舊文，撰定晉禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-27', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '會平，還洛，與裴秀、羊祜共管機密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-28', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '勖以羊祜讓，乃固辭爲侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-29', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '帝甚信重充，與裴秀、王沈、羊祜、荀勖同受腹心之任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-30', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '太傅鄭沖，又與司空荀顗、中書監荀勖、中軍將軍羊祜、中護軍王業，及廷尉杜友、守河南尹杜預、散騎侍郎裴楷、潁川太守周雄、齊相郭頎、騎都尉成公綏荀煇、尚書郎柳軌等，典正其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-31', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '及羊祜等出鎮，充復上表欲立勳邊境，帝並不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-32', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '先是羊祜密啟留充，及是，帝以語充。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-33', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '後參征南軍事，羊祜深知待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-34', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '車騎將軍羊祜雅知濬有奇略，乃密表留濬，於是重拜益州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-35', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '先是，羊祜獲吳間諜，具知情狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-001-0', 'p0263', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」杜預注云：「內黃縣北有戲陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-002-1', 'p0263', 'houhanshu', 'a03-002', '《後漢書·卷二》', '帝生而豐下，杜預注左傳云：「豐下，蓋面方也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-002-2', 'p0263', 'houhanshu', 'a03-002', '《後漢書·卷二》', '」杜預注云：「物謂氣色災變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-003-3', 'p0263', 'houhanshu', 'a03-003', '《後漢書·卷三》', '」杜預注曰：「禁錮勿令仕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-005-4', 'p0263', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」杜預注云：「謂建巳之月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-009-5', 'p0263', 'houhanshu', 'a03-009', '《後漢書·卷九》', '杜預注左傳云「平旦，衆星皆沒，而孛星乃見」，故不言所在之次。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-010b-full-6', 'p0263', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '』」杜預注曰：「厲鬼，趙氏之先祖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-010b-full-7', 'p0263', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」杜預注曰：「懷胎為娠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-016-8', 'p0263', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '」杜預云：「河東大陽縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-017-9', 'p0263', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '杜預注春秋曰：「應國在襄城成父縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-023-10', 'p0263', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '臣融孤弱，介在其閒，杜預注左傳云「介猶閒也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-023-11', 'p0263', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '杜預注左傳曰：「蓼在安豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-024-12', 'p0263', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '」杜預注左傳：「閈，閭門也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-031-13', 'p0263', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '杜預注左傳曰：「充，滿；斥，見也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-032-14', 'p0263', 'houhanshu', 'a03-032', '《後漢書·卷三十二》', '」杜預注曰「𥻦，放也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-032-15', 'p0263', 'houhanshu', 'a03-032', '《後漢書·卷三十二》', '」杜預注云：「錐刀喻小事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-036-16', 'p0263', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '』左傳杜預注曰：「器，車服；名，爵號也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-036-17', 'p0263', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '杜預注曰：「於周為六月，於夏為四月，純陽用事，陰氣未動而侵陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-036-18', 'p0263', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '杜預注云：「祭仲之如宋，非會非聘，見誘被拘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-040-19', 'p0263', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」杜預注左傳云：「方丈為堵，三堵為雉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-040-20', 'p0263', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '杜預注左傳云：「螭，山神，獸形。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-042-21', 'p0263', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '杜預注左傳云：「地中之泉，故曰黃泉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-042-22', 'p0263', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '』」杜預注云：「時士及大夫衰服各有不同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-042-23', 'p0263', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '杜預注云「臺在今南郡華容縣」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-042-24', 'p0263', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」杜預注左傳曰：「郛，郭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-042-25', 'p0263', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '杜預注左傳曰：「今丹水縣北有三戶亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-043-26', 'p0263', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」杜預注云：「美玉名，君所佩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-043-27', 'p0263', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」杜預注云：「比，近也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-043-28', 'p0263', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '杜預注：「乾侯在魏郡斥丘縣，晉境內邑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-049-29', 'p0263', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」杜預注云「鑒，所以自照」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-049-30', 'p0263', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」杜預注云：「不君，失君道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-049-31', 'p0263', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」杜預注云：「春秋之時，以彊弱為大小，衞雖侯爵，猶為小國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-049-32', 'p0263', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」杜預注云：「宣，示也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-049-33', 'p0263', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」杜預注云「鑄刑書於鼎，以為國之常法」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-051-34', 'p0263', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '杜預注左傳云：「織絍，織繒布也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-052-35', 'p0263', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」杜預注云：「周之衰，為刑書，謂之九刑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-052-36', 'p0263', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '杜預注左傳曰：「織絍，織布者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-054-37', 'p0263', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」杜預注曰：「無兾望上位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-054-38', 'p0263', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '今猥規郊城之地，以為苑囿，壞沃衍，杜預注左傳曰：「衍沃，平美之地也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-054-39', 'p0263', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」杜預注曰：「言不復肅敬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-055-40', 'p0263', 'houhanshu', 'a03-055', '《後漢書·卷五十五》', '」杜預注云：「嗣君謂夷昧也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-056-41', 'p0263', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '杜預曰：「加命服之一等。');
