INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-059-46', 'p0263', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」杜預注云：「戲而相愧曰靳。');
