INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-059-49', 'p0263', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '杜預注左傳：「憖，發語之音也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-060a-50', 'p0263', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」杜預注云：「旌夏，大旌也。');
