INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-060a-52', 'p0263', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '杜預注云：「淹滯，有才德而未敘者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-061-53', 'p0263', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '杜預注左傳曰：「短折曰夭，未名曰昏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-061-54', 'p0263', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '」杜預云：「從，順也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-062-55', 'p0263', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '」杜預注左氏云：「器謂車服，名謂爵號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-064-56', 'p0263', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」杜預注曰：「嫠，寡婦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-064-57', 'p0263', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」杜預注曰：「避正寑，過日食時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-064-58', 'p0263', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '杜預注左傳曰：「戕者，卒暴之名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-065-59', 'p0263', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '」本規三歲之費，用五十四億，今適朞年，所耗未半，而餘寇殘燼，杜預注左傳曰：「燼，火餘木也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-066-60', 'p0263', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '杜預注左傳云：「掘地通路曰隧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-066-61', 'p0263', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」杜預注曰：「勃，盛也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-068-62', 'p0263', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」杜預注曰：「黎丘，隰也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-070-63', 'p0263', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」杜預注曰：「斲薄其棺，不使從卿禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-070-64', 'p0263', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」杜預注：「庬，厚大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-070-65', 'p0263', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '杜預注曰：「包，裹束也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-070-66', 'p0263', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」杜預曰：「軍門前大旂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-071-67', 'p0263', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」杜預注云：「于思，多須之貌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-073-68', 'p0263', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」杜預曰：「纍，繫也。');
