INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-70', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」杜預曰：「回軍南向。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-71', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '杜預注曰：「登，成也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-72', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」杜預注曰：「擐，貫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-73', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」杜預注曰：「造，成也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-74', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」杜預注曰：「遠其部曲為離局。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-75', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」杜預注曰：「彌縫猶補合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-074-76', 'p0263', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '杜預注左傳：「陳留酸棗縣北有延津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-075-77', 'p0263', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '杜預注左傳曰：「頷，搖頭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-076-78', 'p0263', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '」杜預注云：「逖，遠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-076-79', 'p0263', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '虎狼當食六畜，杜預注左傳云：「六畜，馬牛羊豕犬雞也。');
