INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-077-81', 'p0263', 'houhanshu', 'a03-077', '《後漢書·卷七十七》', '」杜預注云：「孚，大信也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-078-82', 'p0263', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '杜預注曰：「寺人即閹官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-078-83', 'p0263', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '杜預注曰：「妃嬙，貴者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-078-84', 'p0263', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」杜預注左傳曰：「當國，執政也。');
