INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-080b-88', 'p0263', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '杜預注左傳曰「大人謂在位者」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-080b-89', 'p0263', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」杜預注曰：「遽，畏懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-080b-90', 'p0263', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」杜預注云：「回，邪也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-080b-91', 'p0263', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」於是先解衵衣，杜預注左傳曰：「衵，近身衣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-082-92', 'p0263', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '」杜預注云：「九州之伯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-083-93', 'p0263', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '杜預注左傳曰：「今河南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-94', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '渭南有驪戎，伊、洛閒有楊拒、泉皐之戎，杜預注左傳云：「楊拒，戎邑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-95', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '」杜預注云：「梁南有霍陽山，皆蠻子之邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-96', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '杜預注，戎侵魯，魯人不知，去乃追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-97', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '」杜預注曰：「陰地，河南山北，自上雒以東至陸渾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-089-98', 'p0263', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '杜預注左傳曰：「文馬，畫馬為文也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-090-99', 'p0263', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '其嫁娶則先略女通情，杜預注左傳曰：「不以道取為略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-090-100', 'p0263', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '」杜預注左傳曰：「疽，惡創也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-092-101', 'p0263', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '杜預長曆曰：「書稱『期三百六旬有六日，以閏月定四時成歲，允釐百工，庶績咸熙』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-094-102', 'p0263', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」杜預注曰：「藉稻，履行之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-094-103', 'p0263', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」杜預注曰：「鄅人藉稻，其君自出藉稻，蓋履行之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-098-104', 'p0263', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '杜預注傳曰：「雲物，氣色災變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-108-105', 'p0263', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '杜預曰：「曆家之說，謂日光以望時遙奪月光，故月蝕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-106', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二十九年「盟于狄泉」，杜預曰城內太倉西南池水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-107', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十六年「王宿褚氏」，杜預曰縣南有褚氏亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-108', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳周景王「崩于榮錡氏」，杜預曰鞏縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-109', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十二年單氏「伐東圉」，杜預曰縣東南有圉鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-110', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十三年晉師次于解，杜預曰縣西南有大解、小解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-111', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳定八年「單子伐穀城」，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-112', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」又有甘城，杜預曰縣西南有甘泉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-113', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳宣十二年楚潘黨逐魏錡及熒，杜預曰縣東熒澤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-114', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '卷左傳成十年晉鄭盟脩澤，杜預曰縣東有脩武亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-115', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳莊二十三年「盟于扈」，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-116', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '中牟左傳宣元年諸侯救鄭，遇于北林，杜預曰縣西南有林亭，在鄭北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-117', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳閔二年遇于清，杜預曰縣有清陽亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-118', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰管國也，在京縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-119', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '開封左傳哀十四年「逢澤有介麋」，杜預曰在縣東北，遠，疑
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-120', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳宣元年諸侯會于棐林，杜預曰縣東南有林鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-121', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳成十六年諸侯遷於制田，杜預曰縣東有制澤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-122', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳襄十一年諸侯之師次于瑣，杜預曰縣東有瑣侯亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-123', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　緱氏左傳曰呂相絕秦伯，「殄滅我費、滑」，杜預曰滑國都於費，今緱氏縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-124', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳王取鄔、劉，杜預曰鄔在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-125', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「商湯有景亳之命」，杜預曰縣西南有湯亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-126', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十三年「單子取訾」，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-127', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左氏，周襄王出，國人納之坎埳，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-128', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十二年「王子猛居于皇」，杜預曰有黃亭，在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-129', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰「北制，一名虎牢」，亦即此縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-130', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰鄭子皮勞晉韓宣子于索氏，杜預曰縣東有大索城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-131', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '僖六年諸侯圍新城，杜預曰一名密縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-132', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預遺令曰：「山上有冢，或曰子產，邪東北向新鄭城，不忘本也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-133', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　新城左傳曰文十七年周敗戎于邥垂，杜預曰縣北有垂亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-134', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭十六年楚殺鄤子，杜預曰縣東南有蠻城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-135', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王取鄭隰城，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-136', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '傳又曰却至與周爭鄇田，杜預曰縣西南有鄇人亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-137', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '河陽左傳曰王與鄭盟，杜預曰縣南孟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-138', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '軹左傳曰王以蘇忿生田向與鄭，杜預曰縣西北地名向上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-139', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王與鄭原，杜預曰沁水西北有原城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-140', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王與鄭絺，杜預曰在野王縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-141', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰古雍國，在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-142', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」杜預曰縣西北有攢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-143', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰定元年魏獻子田大陸，杜預曰西北吳澤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-144', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰襄二十三年「救晉，次雍榆」，杜預曰縣東有雍城是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-145', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰僖二十四年晉懷公死高梁，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-146', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰成七年諸侯盟馬陵，杜預曰衞地也，平陽東南地名馬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-147', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰晉改蒐于董，杜預曰縣有董亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-148', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰文十二年秦晉戰河曲，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-149', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '大陽，有吳山，上有虞城，杜預曰虞國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-150', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「秦伐晉，遂自茅津濟」，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-151', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '解左傳曰咎犯與秦晉大夫盟於郇，杜預曰縣西北有郇城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-152', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二十四年晉文公入桑泉，杜預曰在縣西二十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-153', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳文十二年秦侵晉及瑕，杜預曰猗氏縣東北有瑕城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-154', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳閔元年晉滅耿，杜預曰縣東南有耿鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-155', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二年，晉荀息曰「兾為不道」，杜預曰國，在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-156', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰僖三十一年「晉蒐清原」，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-157', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '縣西有絳邑城，杜預曰故絳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-158', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳隱五年曲沃伐翼，杜預曰在縣東八十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-159', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰閔元年晉滅霍，杜預曰「縣東北有霍大山」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-160', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳襄元年晉討宋五大夫，寘諸瓠丘，杜預曰縣東南有壺丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-161', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '北屈左傳曰「二屈」，杜預曰「二」當為「北」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-162', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖八年晉敗狄于采桑，杜預曰縣西南有采桑津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-163', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '蒲子左傳曰晉文公居蒲城，杜預曰今蒲子縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-164', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '弘農故秦函谷關，左傳曰「虢公敗戎于桑田」，杜預曰在縣東北桑田亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-165', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰虢都上陽，在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-166', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖十五年晉侯賂秦，東盡虢略，杜預曰從河曲南行，而東盡故虢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-167', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」杜預曰「畢國在西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-168', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜陵杜預曰古唐杜氏也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-169', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '〕杜預曰：「在鄠縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-170', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　新豐，有驪山，杜預曰：「古驪戎國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-171', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳哀四年「將通於少習」，杜預曰少習，縣東之武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-172', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰哀四年楚右師軍蒼野，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-173', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳晉陰飴甥與秦伯盟王城，杜預曰後改為武鄉，在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-174', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「康有酆宮之朝」，杜預曰有靈臺，康王於是朝諸侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-175', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳曰「夏啟有鈞臺之享」，杜預曰有鈞臺陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-176', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成十七年衞侵鄭，至高氏，杜預曰縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-177', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十八年楚伐鄭，侵雍梁，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-178', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄城左傳定四年「盟皐鼬」，杜預曰縣東南有城皐亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-179', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十八年楚治兵於汾，杜預曰縣東北有汾丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-180', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳謂魚陵，杜預曰魚齒山也，在犨縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-181', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰縣西北有不羹亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-182', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　舞陽邑　郾　臨潁　潁陽　潁陰左傳文九年楚伐鄭，師於狼淵，杜預曰縣西有狼陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-183', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '許左傳莊二十八年楚伐鄭，鄭奔桐丘，杜預曰縣東北有桐丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-184', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '新汲左傳文元年衞孔達侵鄭，伐綿訾及匡，杜預曰縣東北有匡城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-185', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '成十七年伐鄭至曲洧，杜預曰縣治曲洧，城臨洧水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-186', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十一年諸侯師于向，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-187', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳昭四年吳伐楚，入櫟，杜預曰縣東北有櫟亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-188', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成六年楚拒晉桑隧，杜預曰縣東有桑里亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-189', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '召陵左傳昭十三年楚蔡公與子干、子晳盟于鄧，杜預曰縣西南有鄧城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-190', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳僖四年齊伐楚，次陘，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-191', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄四年楚師繁陽，杜預曰鮦陽南有繁陽亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-192', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '春秋左氏傳僖二十一年宋盟鹿上，杜預曰原鹿縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-193', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰：「章華宮在華容縣城內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-194', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '下邑左傳哀七年築黍丘，杜預曰縣西南有黍丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-195', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '昭二十一年敗吳鴻口，杜預曰縣東南有鴻口亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-196', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳十二年楚伐宋，師楊梁，杜預曰有梁亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-197', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二十八年楚子玉夢河神謂己曰「吾賜汝孟諸之麋」，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-198', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二年齊侯盟貫，杜預曰縣西北有貰城，貰字與貫字相似。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-199', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成十六年會沙隨，杜預曰縣北有沙隨亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-200', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰蒙縣西北有薄城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-201', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '相左傳桓十五年會於袲，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-202', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　酇左傳昭四年吳伐楚入棘，杜預曰縣東北有棘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-203', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄元年鄭侵宋，取犬丘，杜預曰縣東北有犬丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-204', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳曰「兾為不道，伐鄍三門」，服虔曰鄍，晉別都，杜預曰是虞邑，地處闕，則非此鄍矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-205', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」左傳僖元年會於檉，杜預曰縣西北有檉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-206', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　柘　新平　扶樂　武平左傳成十六年，諸侯侵陳鳴鹿，杜預曰縣西南有鹿邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-207', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳宋華氏戰于鬼閻，杜預曰縣西北有閻亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-208', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳宣十一年盟辰陵，杜預曰縣東南有辰亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-209', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二十九年介葛盧舍于昌衍，杜預曰縣東南有昌平城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-210', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰：「大庭氏，古國名，在城內，魯於其處作庫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-211', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄四年戰狐台，杜預曰縣東南有目台亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-212', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳文公七年城郚，杜預曰縣南有郚鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-213', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '隱元年盟于蔑，杜預曰蔑，地名，縣南有姑城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-214', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄十七年齊圍桃，杜預曰縣東南有桃墟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-215', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '汶陽左傳桓十二年盟曲池，杜預曰縣北有曲水亭。');
